// Vendors Leaflet (BSD-2-Clause) into the ChatGPT widget as inline strings, so
// the widget loads no external script/style (ChatGPT's widget CSP only needs
// the tile origin in resource_domains).
//
//   npm i --no-save leaflet@1.9.4 && node scripts/build-chatgpt-leaflet.mjs
//   (or: node scripts/build-chatgpt-leaflet.mjs /path/to/leaflet/package)
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = process.argv[2] || join(process.cwd(), "node_modules/leaflet");
const pkg = JSON.parse(readFileSync(join(dir, "package.json"), "utf8"));
let js = readFileSync(join(dir, "dist/leaflet.js"), "utf8").replace(/\n?\/\/# sourceMappingURL=.*$/m, "");
let css = readFileSync(join(dir, "dist/leaflet.css"), "utf8")
  // Image-backed rules (layers control / default marker icon) would request
  // files relative to the sandbox document; the widget uses neither.
  .replace(/background-image:\s*url\([^)]*\);?/g, "")
  .replace(/\/\*[\s\S]*?\*\//g, "")
  .replace(/\s+/g, " ");
if (/<\/script/i.test(js) || /<\/style/i.test(css)) throw new Error("unexpected closing tag in vendored source");
const out = `// GENERATED by frontend/scripts/build-chatgpt-leaflet.mjs — do not edit.
// Leaflet ${pkg.version} (https://leafletjs.com), BSD-2-Clause, (c) Volodymyr Agafonkin and contributors.
/* eslint-disable */
export const LEAFLET_VERSION = ${JSON.stringify(pkg.version)};
export const LEAFLET_CSS = ${JSON.stringify(css.trim())};
export const LEAFLET_JS = ${JSON.stringify(js)};
`;
writeFileSync(join(process.cwd(), "src/lib/chatgpt/vendor/leaflet.generated.ts"), out);
console.log(`leaflet ${pkg.version}: js ${js.length} B, css ${css.length} B`);
